export const UI_TRANSLATIONS: Record<string, UiStrings> = {
  'en-IN': EN_UI,
  'indic-auto': EN_UI,
  'hi-IN': HI_UI,
  'kn-IN': KN_UI,
  'ta-IN': TA_UI,
  'te-IN': TE_UI,
  'ml-IN': ML_UI,
  'bn-IN': BN_UI,
  'mr-IN': MR_UI,
  'gu-IN': GU_UI,
  'pa-IN': PA_UI,
};

export function getUiStrings(language: LanguageCode): UiStrings {
  return UI_TRANSLATIONS[language] || EN_UI;
}
